<?php declare(strict_types=1);
require __DIR__.'/../src/bootstrap.php';use Kulturhus\Verein\{Database,Registry,EventGema};$db=\Kulturhus\Verein\Tests\MySqlFixture::connect(':memory:');Database::migrate($db);$db->exec("INSERT INTO clubs VALUES('a','A');INSERT INTO actors(id,club_id,role,is_superuser) VALUES('admin','a','members',1)");$r=new Registry($db,'admin');$g=new EventGema($db,'admin',$r);$n=0;function check(bool $v,string $s):void{global $n;if(!$v)throw new RuntimeException($s);++$n;echo "PASS $s\n";}function denied(callable $f,string $s):void{try{$f();}catch(DomainException){check(true,$s);return;}throw new RuntimeException($s);}
$event=fn($i)=>$r->saveAppointment(null,0,['title'=>'Festival '.$i,'start'=>'2026-06-01T18:00','end'=>'2026-06-01T21:00','category'=>'verein'],[]);
$d=array_replace(EventGema::defaults(),['status'=>'exempt','reference'=>'G-1','notes'=>'Original checked','nonprofit'=>'yes','voluntary'=>'yes','lower_saxony'=>'yes','free_entry'=>'yes','quota'=>'yes','event_type'=>'club_festival','area'=>'500','live_music'=>'yes','registered_at'=>'2026-05-01T12:00','confirmed_on'=>'2026-05-02','setlist'=>'pending']);
$id=$event(1);denied(fn()=>$g->save($id,0,array_replace($d,['event_type'=>'concert'])),'concert excluded');denied(fn()=>$g->save($id,0,array_replace($d,['area'=>'501'])),'over 500 square metres excluded');denied(fn()=>$g->save($id,0,array_replace($d,['quota'=>'unknown'])),'unverified state quota cannot be confirmed');denied(fn()=>$g->save($id,0,array_replace($d,['registered_at'=>'2026-06-02T12:00'])),'late registration blocks subsidy confirmation');
$g->save($id,0,$d);check($g->get($id)['area']==='500','eligibility persisted');check($g->deadlines($id)['setlist_due']==='2026-07-13','setlist deadline six calendar weeks');check($g->deadlines($id)['setlist_overdue'],'late outstanding setlist visible');foreach([2,3,4] as $i)$g->save($event($i),0,$d);$fifth=$event(5);denied(fn()=>$g->save($fifth,0,$d),'fifth yearly subsidy confirmation blocked');$g->save($fifth,0,array_replace($d,['status'=>'register','planned'=>'1']));check(count(array_filter($g->overview(2026),fn($x)=>$x['status']==='exempt'))===4,'planning does not increase confirmed count');echo "$n GEMA checks passed\n";

$future=$r->saveAppointment(null,0,['title'=>'Neu ohne GEMA','start'=>'2027-06-01T18:00','end'=>'2027-06-01T21:00','category'=>'verein','event_type'=>'club_festival'],[]);
check(in_array($future,array_column($g->upcomingReview(2027),'event_id'),true),'future event appears in the GEMA review without manual GEMA creation');
check($g->upcoming(2026)===[],'past events excluded from current GEMA list');
check(count($g->overview(2026))===5,'past accounting records remain intact');

$g->checklist($future,0,'yes',true,'pending');check($g->get($future)['status']==='registered','simple done marks actual portal registration');$g->checklist($future,1,'no',false,'not_required','Ohne Musiknutzung; vom zuständigen Betreiber geprüft.');check($g->get($future)['status']==='not_required','explicit no requires no duplicate form');

$f=new \Kulturhus\Verein\Finance($db,'admin');$key=fn()=>bin2hex(random_bytes(16));$bill=['kind'=>'expense','description'=>'GEMA Test','amount'=>'100','document_date'=>'2026-09-01','due_date'=>'2026-09-10','category'=>'culture'];
$entry=$f->createEntry($bill,$key(),fn($id)=>$g->linkInvoice($future,2,$id));check($g->get($future)['entry_id']===$entry,'new invoice linked atomically');
$before=(int)$db->query('SELECT COUNT(*) FROM finance_entries')->fetchColumn();denied(fn()=>$f->createEntry($bill,$key(),fn($id)=>$g->linkInvoice($future,0,$id)),'stale event prevents invoice creation');check((int)$db->query('SELECT COUNT(*) FROM finance_entries')->fetchColumn()===$before,'failed linkage rolls back finance entry');
$other=$r->saveAppointment(null,0,['title'=>'Other','start'=>'2027-07-01T18:00','end'=>'2027-07-01T21:00','category'=>'verein'],[]);denied(fn()=>$g->linkInvoice($other,0,$entry),'same invoice cannot be assigned twice');
$png=base64_decode('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+jRZkAAAAASUVORK5CYII=');$uploadKey=$key();$doc=$g->uploadInvoice($future,$entry,'rechnung.png',$png,$uploadKey);check($g->uploadInvoice($future,$entry,'rechnung.png',$png,$uploadKey)===$doc,'repeated upload creates no duplicate');
$docs=new \Kulturhus\Verein\Documents($db,'admin');check(count($docs->listing(['source_type'=>'entry','source_id'=>$entry]))===1,'event upload available on same finance entry');
$account=$f->createAccount('Testbank','offline','0','2026-09-01');foreach(['40','60'] as $amount){$t=$f->createTransaction(['account'=>$account,'booked_on'=>'2026-09-02','direction'=>'expense','amount'=>$amount,'description'=>'Manuelle Zuordnung'],$key());$f->allocate($t,$f->transactionDetail($t)['version'],$entry,$f->entry($entry)['version'],$amount,$key());$row=array_column($g->overview(2027),null,'event_id')[$future];check($row['payment_state']===($amount==='40'?'Teilbezahlt':'Bezahlt'),'GEMA status follows finance allocation '.$amount);}
